#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// CheckedListBox's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/checked_list_box.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// Whether the first click on an unselected row also toggles its check (CheckOnClick); off by default, so the first click only selects.
template <typename Declaring>
struct CheckedListBoxCheckOnClickCapability {
    PropertyCell<bool, CheckedListBoxCheckOnClickCapability<Declaring>> check_on_click{};

    static void assign(CheckedListBoxCheckOnClickCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.check_on_click), incoming);
        if (!capability.check_on_click.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.check_on_click));
    }
};

// The check box's side in logical pixels, 8 to 32 (std::out_of_range otherwise); the row text starts after it.
template <typename Declaring>
struct CheckedListBoxIndicatorSizeCapability {
    PropertyCell<double, CheckedListBoxIndicatorSizeCapability<Declaring>> indicator_size{14.0};

    static void assign(CheckedListBoxIndicatorSizeCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.indicator_size), incoming);
        if (!capability.indicator_size.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.indicator_size));
    }
};

// Every CheckedListBox capability, in the order the declaring class takes them.
template <typename Declaring>
struct CheckedListBoxCapabilities : public CheckedListBoxCheckOnClickCapability<Declaring>,
                                    public CheckedListBoxIndicatorSizeCapability<Declaring> {};

} // namespace gui_forms
